18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /**
30	     * Returns the owner's membership tier: {@code "SILVER"} when the owner has no namesakes
31	     * (namesakeCount is 0) and an email address is present, otherwise {@code "BRONZE"}.
32	     */
33	    default String membershipTier(Owner owner) {
34	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
35	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
36	        return (noNamesakes && hasEmail) ? "SILVER" : "BRONZE";
37	    }
38	
39	    /**
40	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
41	     * the registrationDate year (e.g. 'SMI-0007-M26'). Returns {@code null} when either the
42	     * customer code or the registration date is absent (e.g. legacy seed owners).
43	     */
44	    default String membershipNumber(Owner owner) {
45	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
46	            return null;
47	        }
48	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
49	    }
50	
51	    Owner toOwner(OwnerDto ownerDto);
52	
53	    @Mapping(target = "id", ignore = true)
54	    @Mapping(target = "pets", ignore = true)
55	    Owner toOwner(OwnerFieldsDto ownerDto);
56	
57	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
58	
59	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
60	
61	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
62	        OwnerPageDto ownerPageDto = new OwnerPageDto();
63	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
64	        ownerPageDto.setPage(ownerPage.getNumber());
65	        ownerPageDto.setSize(ownerPage.getSize());
66	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
67	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
68	        return ownerPageDto;
69	    }
70	}
